// CreateTableWithDBType creates the Sales_Invoice_Header table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *SalesInvoiceHeader) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesInvoiceHeaderTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetSalesInvoiceHeaderPostgresTableSchema()
	} else {
		schema = GetSalesInvoiceHeaderTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Sales_Invoice_Header table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *SalesInvoiceHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, SalesInvoiceHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Sales_Invoice_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (sell_to_customer_no)`,
		fmt.Sprintf("%s$Sales_Invoice_Header$customer", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer: %w", err)
	}
	var keys []sift.Key
	for _, spec := range salesInvoiceHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, SalesInvoiceHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, SalesInvoiceHeaderTableName, keys)
}

// salesInvoiceHeaderSIFTSpecs are the table's keys with sum_index_fields
func salesInvoiceHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *SalesInvoiceHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, SalesInvoiceHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range salesInvoiceHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, SalesInvoiceHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: SalesInvoiceHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, SalesInvoiceHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

