// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *SalesInvoiceHeader) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, SalesInvoiceHeaderTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "payment_discount_percent":
			column = "payment_discount_percent"
		case "currency_factor":
			column = "currency_factor"
		case "no_printed":
			column = "no_printed"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Sales_Invoice_Header", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Sales_Invoice_Header.%s: %w", column, err)
		}
		switch column {
		case "payment_discount_percent":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Sales_Invoice_Header.%s: %w", column, err)
			}
			t.Payment_discount_percent = d
		case "currency_factor":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Sales_Invoice_Header.%s: %w", column, err)
			}
			t.Currency_factor = d
		case "no_printed":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Sales_Invoice_Header.%s: %w", column, err)
			}
			t.No_printed = int(f)
		}
	}
	return nil
}

